/**
 * Pillar-/Supporting-Content für SofortTools. Die Inhalte werden aus
 * redaktionell gepflegten Themenbausteinen zu vollständigen Ratgebern gebaut.
 */
export type GuideBlock =
  | { type: "p"; text: string }
  | { type: "ul"; items: string[] }
  | { type: "ol"; items: string[] }
  | { type: "h3"; text: string }
  | { type: "tip"; text: string }
  | { type: "table"; head: string[]; rows: string[][] };

export type Guide = {
  slug: string;
  title: string;
  description: string;
  keywords: string[];
  toolSlug: string;
  toolSlugs?: string[];
  excerpt: string;
  updated: string;
  kind: "pillar" | "supporting";
  cluster: string;
  relatedGuideSlugs: string[];
  sections: { h2: string; blocks: GuideBlock[] }[];
};

type GuideSeed = Omit<Guide, "sections"> & {
  topic: string;
  intro: string;
  method: string;
  essentials: string[];
  tableHead?: [string, string, string];
  table: string[][];
  pitfalls: string[];
  example: string;
};

function buildGuide(seed: GuideSeed): Guide {
  return {
    ...seed,
    sections: [
      {
        h2: `Worum es bei ${seed.topic} wirklich geht`,
        blocks: [
          { type: "p", text: seed.intro },
        ],
      },
      {
        h2: "Diese Angaben brauchst du",
        blocks: [
          { type: "ul", items: seed.essentials },
        ],
      },
      {
        h2: "So gehst du bei der Rechnung vor",
        blocks: [
          { type: "p", text: seed.method },
        ],
      },
      {
        h2: "Ein konkretes Beispiel",
        blocks: [
          { type: "p", text: seed.example },
          { type: "table", head: seed.tableHead ?? ["Prüfpunkt", "Ansatz oder Rechenweg", "Ergebnis oder Grundlage"], rows: seed.table },
        ],
      },
      {
        h2: "Diese Fehler verfälschen das Ergebnis",
        blocks: [
          { type: "ul", items: seed.pitfalls },
        ],
      },
    ],
  };
}

